IF OBJECT_ID('dbo.SearchResultsLog', 'U') IS NOT NULL
    DROP TABLE dbo.SearchResultsLog;

CREATE TABLE dbo.SearchResultsLog (
    id INT IDENTITY(1,1) PRIMARY KEY,
    Timestamp DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),
    Title NVARCHAR(512) NULL,
    URL NVARCHAR(2048) NOT NULL,
    Content NVARCHAR(MAX) NULL
);

parameters.jsCode:
function clean(str) {
  return str
    .replace(/'/g, "''")
    .replace(/;/g, "")
    .replace(/\bUSE\b\s+\w+/gi, "")
    .replace(/\bDROP\b\s+\w+/gi, "")
    .replace(/\bOPENAI\b/gi, "")
    .replace(/\bAI\b/gi, "")
    .replace(/[\u0000-\u001F\u007F-\u009F]/g, "");
}

return [
  {
    json: {
      values: [
        {
          url: $json.results[0].url,
          title: $json.results[0].title,
          content: clean($json.results[0].content)
        },
        {
          url: $json.results[1].url,
          title: $json.results[1].title,
          content: clean($json.results[1].content)
        },
        {
          url: $json.results[2].url,
          title: $json.results[2].title,
          content: clean($json.results[2].content)
        }
      ]
    }
  }
];
